@Logged public class Robot extends TimedRobot {
  public Robot() {
    Epilogue.configure(cfg -> {
      cfg.backend = new FileBackend(DataLogManager.getLog());
      cfg.root = "Telemetry";
      cfg.minimumImportance = Logged.Importance.CRITICAL;
      if (isSimulation()) cfg.errorHandler = ErrorHandler.crashOnError();
    });
    Epilogue.bind(this);
  }
}

