ReplayReport r = RootstockReplay.verify(Path.of("logs/ref/q42.wpilog"))
    .ignoring("RealOutputs/LoggedTracer/**", "RealOutputs/SystemStats/**")
    .withTolerance("RealOutputs/Drive/Pose", 1e-6);
assertTrue(r.cycleMatchFraction() > 0.9999, r.summary());

public final class Elevator extends RootstockSubsystem {
  // Declarative kinematic chain; index order MUST match config.json components[]
  private static final MechanismSpec SPEC = MechanismSpec.builder()
      .prismatic("Stage1", new Pose3d(0.0, 0.0, 0.10, Rotation3d.kZero), Axis.Z, Meters)
      .prismatic("Carriage", Parent.of("Stage1"), Axis.Z, Meters)
      .revolute("Arm", Parent.of("Carriage"),
                new Transform3d(0.15, 0.0, 0.05, Rotation3d.kZero), Axis.Y, Radians)
      .build();

  private final MechanismVisualizer viz = SPEC.visualizer("Elevator");

  @Override public void periodic() {
    viz.measured().set("Stage1", stage1M).set("Carriage", carriageM).set("Arm", armRad);
    viz.setpoint().set("Carriage", profileSetpointM).set("Arm", profileSetpointRad);
    viz.goal().set("Carriage", goalM).set("Arm", goalRad);
    viz.log();  // one call, everything below is emitted
  }
}
// Emits:
